package biotex;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;

import static biotex.JsonStore.*;

public final class JsonService {
    private final JsonStore store;
    public JsonService(JsonStore store){this.store=store;}
    public List<Map<String,Object>> rows(String table){return store.read(s->copy(s.table(table)));}
    public Map<String,Object> one(String table,long id){return store.read(s->new LinkedHashMap<>(s.byId(table,id)));}
    public List<Map<String,Object>> productChildren(String table,long product){return store.read(s->s.table(table).stream().filter(r->num(r.get("productId"))==product).map(LinkedHashMap::new).map(x->(Map<String,Object>)x).toList());}
    public long addProduct(String code,String name,String category,String size,boolean sterile)throws Exception{return store.update(s->{if(name==null||name.isBlank())throw new IllegalArgumentException("Ürün adı gerekli");if(s.products.stream().anyMatch(x->Objects.equals(x.get("code"),code)))throw new IllegalArgumentException("Ürün kodu kullanılıyor");var r=s.add("products",map("code",code,"name",name,"category",category,"size",size,"sterile",sterile,"active",true,"revision",1,"profileId",1));long id=num(r.get("id"));s.log("products",id,"CREATE",name);return id;});}
    public void updateProduct(long id,Map<String,Object> fields)throws Exception{store.update(s->{var p=s.byId("products",id);p.putAll(fields);p.put("revision",num(p.get("revision"))+1);s.log("products",id,"UPDATE",str(p.get("name")));return null;});}
    public long copyProduct(long original,String newCode)throws Exception{return store.update(s->{var p=s.byId("products",original);if(s.products.stream().anyMatch(x->Objects.equals(x.get("code"),newCode)))throw new IllegalArgumentException("Ürün kodu kullanılıyor");var fields=new LinkedHashMap<>(p);fields.remove("id");fields.put("code",newCode);fields.put("name",p.get("name")+" - Kopya");fields.put("revision",1);fields.remove("importHash");long copyId=num(s.add("products",fields).get("id"));Map<Long,Long> comps=new HashMap<>();for(var r:new ArrayList<>(s.components))if(num(r.get("productId"))==original){var f=new LinkedHashMap<>(r);f.remove("id");f.put("productId",copyId);comps.put(num(r.get("id")),num(s.add("components",f).get("id")));}
        for(var r:new ArrayList<>(s.operations))if(num(r.get("productId"))==original){var f=new LinkedHashMap<>(r);f.remove("id");f.put("productId",copyId);if(f.get("componentId")!=null)f.put("componentId",comps.get(num(f.get("componentId"))));s.add("operations",f);}
        for(var r:new ArrayList<>(lines(s)))if(num(r.get("productId"))==original){var f=new LinkedHashMap<>(r);f.remove("id");f.put("productId",copyId);if(f.get("componentId")!=null)f.put("componentId",comps.get(num(f.get("componentId"))));addLineState(s,f);}
        s.log("products",copyId,"COPY","Kaynak "+original);return copyId;});}
    // Recipe lines are held in their own JSON array, initialized lazily for old schema snapshots.
    @SuppressWarnings("unchecked") private static List<Map<String,Object>> lines(JsonStore.State s){return s.recipeLines;}
    private static Map<String,Object> addLineState(JsonStore.State s,Map<String,Object> fields){var f=new LinkedHashMap<>(fields);f.put("id",s.nextId++);lines(s).add(f);return f;}
    public List<Map<String,Object>> lines(long product){return store.read(s->lines(s).stream().filter(r->num(r.get("productId"))==product).map(LinkedHashMap::new).map(x->(Map<String,Object>)x).toList());}
    public long addComponent(long product,String name,String qty)throws Exception{return store.update(s->{s.byId("products",product);long pos=s.components.stream().filter(r->num(r.get("productId"))==product).count()+1;var c=s.add("components",map("productId",product,"position",pos,"name",name,"quantity",qty,"purchased",false));long id=num(c.get("id"));s.log("components",id,"CREATE",name);return id;});}
    private boolean reaches(JsonStore.State s,long start,long target,Set<Long> seen){if(start==target)return true;if(!seen.add(start))return false;for(var c:s.components)if(num(c.get("productId"))==start&&c.get("subproductId")!=null&&reaches(s,num(c.get("subproductId")),target,seen))return true;return false;}
    public void linkSubproduct(long component,long child,boolean purchased)throws Exception{store.update(s->{var c=s.byId("components",component);s.byId("products",child);if(reaches(s,child,num(c.get("productId")),new HashSet<>()))throw new IllegalArgumentException("Çevrimsel alt ürün bağımlılığı");c.put("subproductId",child);c.put("purchased",purchased);s.log("components",component,"LINK","Alt ürün "+child);return null;});}
    public long addMaterial(String code,String name,String unit,String gsm)throws Exception{return store.update(s->{if(s.materials.stream().anyMatch(r->Objects.equals(r.get("code"),code)))throw new IllegalArgumentException("Stok kodu kullanılıyor");return num(s.add("materials",map("code",code,"name",name,"unit",unit,"gsm",gsm,"active",true)).get("id"));});}
    public long addPrice(long material,String supplierName,String amount,String currency,String date,boolean selected)throws Exception{return store.update(s->{s.byId("materials",material);var supplier=s.suppliers.stream().filter(r->Objects.equals(r.get("name"),supplierName)).findFirst().orElseGet(()->s.add("suppliers",map("name",supplierName)));if(selected)for(var p:s.prices)if(num(p.get("materialId"))==material)p.put("selected",false);return num(s.add("prices",map("materialId",material,"supplierId",num(supplier.get("id")),"amount",amount,"currency",currency,"validFrom",date,"selected",selected)).get("id"));});}
    public void selectPrice(long price)throws Exception{store.update(s->{var chosen=s.byId("prices",price);long material=num(chosen.get("materialId"));for(var p:s.prices)if(num(p.get("materialId"))==material)p.put("selected",num(p.get("id"))==price);return null;});}
    public void addRate(String date,String currency,String rate)throws Exception{store.update(s->{var found=s.rates.stream().filter(r->Objects.equals(r.get("date"),date)&&Objects.equals(r.get("currency"),currency)).findFirst();if(found.isPresent())found.get().put("tryPerUnit",rate);else s.add("rates",map("date",date,"currency",currency,"tryPerUnit",rate));return null;});}
    public long addLine(Map<String,Object> fields)throws Exception{return store.update(s->{long product=num(fields.get("productId"));s.byId("products",product);var line=addLineState(s,fields);long id=num(line.get("id"));s.log("lines",id,"CREATE",str(line.get("description")));return id;});}
    public void updateLine(long id,Map<String,Object> fields)throws Exception{store.update(s->{var r=lines(s).stream().filter(x->num(x.get("id"))==id).findFirst().orElseThrow();r.putAll(fields);s.log("lines",id,"UPDATE",str(r.get("description")));return null;});}
    public long addOperation(Map<String,Object> fields)throws Exception{return store.update(s->{long product=num(fields.get("productId"));s.byId("products",product);return num(s.add("operations",fields).get("id"));});}
    public void updateOperation(long id,Map<String,Object> fields)throws Exception{store.update(s->{s.byId("operations",id).putAll(fields);s.log("operations",id,"UPDATE",str(fields.get("name")));return null;});}
    public long addProfile(String name,String factor,String extra,String markup,String method,String labor)throws Exception{return store.update(s->num(s.add("profiles",map("name",name,"lineFactor",factor,"extraRate",extra,"markupRate",markup,"markupMethod",method,"laborMethod",labor)).get("id")));}
    public void assignProfile(long product,long profile)throws Exception{store.update(s->{s.byId("profiles",profile);s.byId("products",product).put("profileId",profile);return null;});}
    public long addRule(Map<String,Object> fields)throws Exception{return store.update(s->num(s.add("rules",fields).get("id")));}
    public long addCustomer(String name,String address,String taxId)throws Exception{return store.update(s->num(s.add("customers",map("name",name,"address",address,"taxId",taxId)).get("id")));}
    private CostEngine.Estimate calculate(JsonStore.State s,long product,String quantity,String date,Set<Long> stack){
        if(!stack.add(product))throw new IllegalArgumentException("Çevrimsel alt ürün bağımlılığı");
        try{var p=s.byId("products",product);var profile=s.byId("profiles",num(p.get("profileId")));List<CostEngine.Line> recipe=new ArrayList<>();Set<Long> manufactured=new HashSet<>();
            for(var c:s.components)if(num(c.get("productId"))==product&&c.get("subproductId")!=null){long cid=num(c.get("id"));if(Boolean.TRUE.equals(c.get("purchased"))){if(lines(s).stream().noneMatch(r->num(r.get("componentId"))==cid))recipe.add(new CostEngine.Line("Satın alınan alt ürün: "+c.get("name"),"MANUAL","AD",null,null,"1",str(c.get("quantity")),"0",null,"TRY",null,"1",null));}else{manufactured.add(cid);var child=calculate(s,num(c.get("subproductId")),"1",date,stack);recipe.add(new CostEngine.Line("Alt ürün: "+c.get("name"),"MANUAL","AD",null,null,"1",str(c.get("quantity")),"0",child.unitCost()==null?null:child.unitCost().toPlainString(),"TRY",null,"1",null));}}
            for(var r:lines(s))if(num(r.get("productId"))==product&&!manufactured.contains(num(r.get("componentId")))){
                String price=str(r.get("manualPrice")),currency=str(r.get("manualCurrency")),gsm=null;
                if(r.get("materialId")!=null){long mid=num(r.get("materialId"));gsm=str(s.byId("materials",mid).get("gsm"));if(price==null){var chosen=s.prices.stream().filter(x->num(x.get("materialId"))==mid&&Boolean.TRUE.equals(x.get("selected"))).findFirst();if(chosen.isPresent()){price=str(chosen.get().get("amount"));currency=str(chosen.get().get("currency"));}}}
                if(currency==null||currency.equals("TRL"))currency="TRY";String rate=null;
                if(!currency.equals("TRY")){String cur=currency;rate=s.rates.stream().filter(x->Objects.equals(x.get("currency"),cur)&&str(x.get("date")).compareTo(date)<=0).max(Comparator.comparing(x->str(x.get("date")))).map(x->str(x.get("tryPerUnit"))).orElse(null);}
                recipe.add(new CostEngine.Line(str(r.get("description")),str(r.get("method")),str(r.get("unit")),str(r.get("widthCm")),str(r.get("heightCm")),str(r.get("repeats")),str(r.get("manualQty")),str(r.get("wasteRate")),price,currency,rate,r.get("costFactor")==null?str(profile.get("lineFactor")):str(r.get("costFactor")),gsm));
            }
            List<CostEngine.Operation> operations=new ArrayList<>();for(var r:s.operations)if(num(r.get("productId"))==product)operations.add(new CostEngine.Operation(str(r.get("name")),str(r.get("duration")),str(r.get("timeUnit")),str(r.get("people")),str(r.get("repeats")),str(r.get("minuteRate")),str(r.get("tolerance")),"CORRECTED".equals(profile.get("laborMethod")),str(r.get("scope"))));
            List<CostEngine.Rule> rules=new ArrayList<>();for(var r:s.rules)if(num(r.get("profileId"))==num(profile.get("id"))&&!Boolean.FALSE.equals(r.get("active")))rules.add(new CostEngine.Rule(str(r.get("name")),str(r.get("kind")),str(r.get("basis")),str(r.get("rate")),str(r.get("amount")),str(r.get("divisor")),Boolean.TRUE.equals(r.get("sterileOnly")),str(r.get("scope"))));
            if(CostEngine.d(str(profile.get("extraRate"))).signum()!=0)rules.add(new CostEngine.Rule("Ek gider","RATE","SUBTOTAL",str(profile.get("extraRate")),null,null,false,"PRODUCT"));
            return CostEngine.estimate(recipe,operations,rules,quantity,str(profile.get("markupRate")),str(profile.get("markupMethod")),Boolean.TRUE.equals(p.get("sterile")));
        }finally{stack.remove(product);}
    }
    public CostEngine.Estimate calculate(long product,String quantity,String date){return store.read(s->calculate(s,product,quantity,date,new HashSet<>()));}
    public long saveEstimate(long product,String quantity,String date,long customer,boolean approve)throws Exception{return store.update(s->{var result=calculate(s,product,quantity,date,new HashSet<>());if(approve&&!result.approvable())throw new IllegalArgumentException("Onay engellendi: "+String.join("; ",result.issues()));var p=s.byId("products",product);Map<String,Object> snapshot=map("product",new LinkedHashMap<>(p),"components",s.components.stream().filter(x->num(x.get("productId"))==product).map(LinkedHashMap::new).toList(),"recipeLines",lines(s).stream().filter(x->num(x.get("productId"))==product).map(LinkedHashMap::new).toList(),"operations",s.operations.stream().filter(x->num(x.get("productId"))==product).map(LinkedHashMap::new).toList(),"profile",new LinkedHashMap<>(s.byId("profiles",num(p.get("profileId")))),"prices",copy(s.prices),"rates",copy(s.rates),"rules",copy(s.rules),"materialCost",result.material().toPlainString(),"laborCost",result.labor().toPlainString(),"extraCost",result.extras().toPlainString(),"orderFixed",result.orderFixed().toPlainString(),"unitCost",result.unitCost()==null?null:result.unitCost().toPlainString(),"unitPrice",result.unitPrice()==null?null:result.unitPrice().toPlainString(),"orderTotal",result.orderTotal()==null?null:result.orderTotal().toPlainString(),"issues",result.issues(),"rateDate",date,"quantity",quantity);String customerName=customer==0?null:str(s.byId("customers",customer).get("name"));return num(s.add("estimates",map("productId",product,"productName",p.get("name"),"customerId",customer==0?null:customer,"customerName",customerName,"quantity",quantity,"status",approve?"APPROVED":"DRAFT","createdAt",Instant.now().toString(),"currency","TRY","unitCost",result.unitCost()==null?null:result.unitCost().toPlainString(),"unitPrice",result.unitPrice()==null?null:result.unitPrice().toPlainString(),"orderTotal",result.orderTotal()==null?null:result.orderTotal().toPlainString(),"snapshot",snapshot)).get("id"));});}
    public record Demand(long materialId,String code,String name,String unit,BigDecimal quantity){}
    public List<Demand> demand(long product,String quantity){return store.read(s->{BigDecimal order=CostEngine.required(quantity,"Sipariş adedi");if(order.signum()<=0)throw new IllegalArgumentException("Sipariş adedi sıfırdan büyük olmalı");Map<String,Demand> out=new LinkedHashMap<>();for(var r:lines(s))if(num(r.get("productId"))==product&&r.get("materialId")!=null){long mid=num(r.get("materialId"));var m=s.byId("materials",mid);String unit=str(r.get("unit"));var line=new CostEngine.Line(str(r.get("description")),str(r.get("method")),unit,str(r.get("widthCm")),str(r.get("heightCm")),str(r.get("repeats")),str(r.get("manualQty")),str(r.get("wasteRate")),"0","TRY",null,"1",str(m.get("gsm")));var result=CostEngine.line(line);if(!result.issues().isEmpty())throw new IllegalArgumentException(String.join("; ",result.issues()));String key=mid+"|"+unit;BigDecimal amount=result.costQuantity().multiply(order,CostEngine.MC);Demand old=out.get(key);out.put(key,new Demand(mid,str(m.get("code")),str(m.get("name")),unit,old==null?amount:old.quantity.add(amount,CostEngine.MC)));}return new ArrayList<>(out.values());});}
}
